const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const samples=[
{id:'s1',company:'Meridian Labs',role:'Machine Learning Intern',type:'Internship',location:'Gainesville, FL',tags:['Python','Machine learning','Research'],description:'Build practical tools that bring machine learning into everyday decisions.',color:'#eae8ff',ink:'#7561b4',symbol:'M'},
{id:'s2',company:'Forma',role:'Product Engineering Intern',type:'Internship',location:'Remote',tags:['React','JavaScript','Product'],description:'Turn thoughtful product ideas into simple, useful experiences.',color:'#fbeee9',ink:'#c17956',symbol:'f'},
{id:'s3',company:'Northstar Research',role:'Undergraduate Researcher',type:'Research',location:'Gainesville, FL',tags:['Python','Data analysis','Research'],description:'Explore how data can help us ask better questions about the world.',color:'#e8effb',ink:'#4d70b6',symbol:'✳'},
{id:'s4',company:'Arc Studio',role:'Frontend Developer',type:'Full-time',location:'Remote',tags:['React','CSS','JavaScript'],description:'Craft accessible interfaces for a new generation of creative tools.',color:'#e9f1ee',ink:'#638678',symbol:'a'},
{id:'s5',company:'Fieldwork',role:'Data Science Intern',type:'Internship',location:'Austin, TX',tags:['Python','SQL','Data analysis'],description:'Make complex environmental data more useful and understandable.',color:'#fcf3df',ink:'#ba9646',symbol:'↟'},
{id:'s6',company:'Common Ground',role:'Research Assistant',type:'Research',location:'New York, NY',tags:['Research','Writing','Data analysis'],description:'Connect community insights with research that creates real impact.',color:'#f2eaf3',ink:'#9a70a1',symbol:'c'}].map(o=>({...o,sample:true}));
let state;try{state=JSON.parse(localStorage.getItem('nudge-v1'))}catch{}state={profile:{name:'',headline:'',skills:'',experience:'',voice:''},saved:[],drafts:[],custom:[],...state};let view='discover',filter='All opportunities',query='',locationFilter='Anywhere';
const all=()=>[...state.custom,...samples];const get=id=>all().find(o=>o.id===id);const skills=()=>state.profile.skills.split(',').map(s=>s.trim().toLowerCase()).filter(Boolean);const matched=o=>o.tags.filter(t=>skills().some(s=>t.toLowerCase().includes(s)||s.includes(t.toLowerCase())));
function persist(){try{localStorage.setItem('nudge-v1',JSON.stringify(state));return true}catch{toast('Browser storage is unavailable. Export your work before leaving.');return false}}
function toast(t){if(document.querySelector('#modal').open){let n=document.querySelector('#dialog-status');if(!n){n=document.createElement('p');n.id='dialog-status';n.className='note';n.setAttribute('role','status');document.querySelector('.modal-body').append(n)}n.textContent=t;}$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function modal(title,sub,body){$('#modal-content').innerHTML=`<div class="modal-head"><div><div class="eyebrow">MAKE THE FIRST MOVE</div><h2>${title}</h2><p>${sub}</p></div><button class="close" aria-label="Close dialog">×</button></div><div class="modal-body">${body}</div>`;$('#modal').showModal();$('.close').onclick=()=>$('#modal').close()}
function page(){document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#breadcrumb').innerHTML=`Workspace <i>/</i> ${{discover:'Discover',saved:'Shortlist',drafts:'Drafts',activity:'Outreach',profile:'Your profile'}[view]}`;$('#saved-count').textContent=state.saved.length;$('#draft-count').textContent=state.drafts.filter(d=>!d.status||d.status==='Draft').length;if(view==='discover'||view==='saved')discover();else if(view==='profile')profile();else drafts();}
function card(o){const m=matched(o);return `<article class="card"><div class="card-top"><span class="company-icon" style="background:${o.color||'#edf1ff'};color:${o.ink||'#526baf'}">${esc(o.symbol||o.company[0])}</span><button class="bookmark ${state.saved.includes(o.id)?'selected':''}" data-save="${o.id}" aria-label="${state.saved.includes(o.id)?'Remove from':'Add to'} shortlist">${state.saved.includes(o.id)?'♥':'♡'}</button></div><div class="company">${esc(o.company)}</div><h3>${esc(o.role)}</h3><div class="meta">⌖ ${esc(o.location)} &nbsp; · &nbsp; ${esc(o.type)}</div><div class="tags">${o.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><div class="fit">${m.length?'✧ '+m.length+' matching skill'+(m.length>1?'s':''):'✧ '+(skills().length?'Explore a new direction':'Add your skills to see your fit')}</div><p class="card-desc">${esc(o.description)}</p><div class="card-foot"><span>${o.sample?'Illustrative opportunity':'Added by you'}</span><button class="primary" data-open="${o.id}">Explore opportunity ↗</button></div></article>`}
function discover(){const saved=view==='saved';$('#content').innerHTML=`${!saved?`<section class="hero"><div class="eyebrow">YOUR NEXT CHAPTER STARTS HERE</div><h1>Great things start with<br><span>a little nudge.</span></h1><p>Find your people. Tell your story.<br>Turn a first hello into your next opportunity.</p><button class="primary" id="hero-profile">${state.profile.name?'Refine your profile':'Build your profile'} <span style="margin-left:20px">↗</span></button><div class="hero-art" aria-hidden="true"><div class="orbit"></div><div class="orbit"></div><div class="orbit"></div><div class="orbit"></div><span class="mini-star">✳</span><div class="floating">↗</div><div class="tiny-mail">✉</div></div></section><section class="stats"><div class="stat"><span class="stat-icon">◈</span><div><strong>${state.custom.length}</strong><small>Your opportunities</small></div></div><div class="stat"><span class="stat-icon">♡</span><div><strong>${state.saved.length.toString().padStart(2,'0')}</strong><small>On your shortlist</small></div></div><div class="stat"><span class="stat-icon">↗</span><div><strong>${state.drafts.filter(d=>d.status==='Sent'||d.status==='Replied').length.toString().padStart(2,'0')}</strong><small>Conversations started</small></div></div></section>`:''}<div class="section-head"><div><h2>${saved?'Your shortlist':'A world of possibilities'}</h2><p>${saved?'Good possibilities, all in one place.':'Find a place where your skills can make a difference.'}</p></div><button class="secondary" id="add">＋ Add opportunity</button></div><div class="toolbar"><div class="search"><input id="search" placeholder="Search roles, companies, or skills" aria-label="Search opportunities" value="${esc(query)}"></div><select id="location" aria-label="Location filter"><option>Anywhere</option><option>Remote</option><option>Gainesville, FL</option><option>Austin, TX</option><option>New York, NY</option></select></div><div class="tabs">${['All opportunities','Internship','Research','Full-time'].map(t=>`<button data-filter="${t}" class="${filter===t?'active':''}">${t}</button>`).join('')}<span class="sample-note">Sample listings are illustrative, not live openings.</span></div><div class="grid" id="cards"></div>`;$('#location').value=locationFilter;$('#search').oninput=e=>{query=e.target.value;cards()};$('#location').onchange=e=>{locationFilter=e.target.value;cards()};$('#add').onclick=addOpportunity;if($('#hero-profile'))$('#hero-profile').onclick=()=>navigate('profile');document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;discover()});cards()}
function cards(){let list=all().filter(o=>(view!=='saved'||state.saved.includes(o.id))&&(filter==='All opportunities'||o.type===filter)&&(locationFilter==='Anywhere'||o.location===locationFilter)&&`${o.company} ${o.role} ${o.tags.join(' ')}`.toLowerCase().includes(query.toLowerCase()));list.sort((a,b)=>matched(b).length-matched(a).length);$('#cards').innerHTML=list.length?list.map(card).join(''):`<div class="empty"><h3>${view==='saved'?'Make room for possibilities.':'No matches just yet.'}</h3><p>${view==='saved'?'Save an opportunity with the heart icon to see it here.':'Try another search, or add an opportunity you have found.'}</p><button class="secondary" id="reset-filter">${view==='saved'?'Explore opportunities':'Clear filters'}</button></div>`;document.querySelectorAll('[data-save]').forEach(b=>b.onclick=()=>{const id=b.dataset.save;state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];persist();page()});document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>opportunity(b.dataset.open));if($('#reset-filter'))$('#reset-filter').onclick=()=>{query='';filter='All opportunities';locationFilter='Anywhere';navigate('discover')}}
function addOpportunity(){modal('A possibility worth exploring.','Add a role, a research group, or a team you would love to join.',`<form id="op-form"><div class="row"><label class="field">Company or organization<input name="company" required maxlength="100"></label><label class="field">Role or area of interest<input name="role" required maxlength="120"></label></div><div class="row"><label class="field">Opportunity type<select name="type"><option>Internship</option><option>Research</option><option>Full-time</option></select></label><label class="field">Location<input name="location" required placeholder="Remote or city"></label></div><label class="field">Relevant skills<input name="tags" placeholder="Python, Research, Writing" required></label><label class="field">What interests you about their work?<textarea name="description" required maxlength="1500" placeholder="Use details you can verify from the opportunity or company page."></textarea></label><label class="field">Source URL (optional)<input name="url" type="url" placeholder="https://..."></label><div class="actions"><button class="primary">Save opportunity ↗</button></div></form>`);$('#op-form').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));if(data.url&&!/^https?:\/\//i.test(data.url)){toast('Use an http or https source URL.');return}state.custom.unshift({...data,id:crypto.randomUUID(),tags:data.tags.split(',').map(t=>t.trim()).filter(Boolean).slice(0,12),sample:false});persist();$('#modal').close();page();toast('Opportunity added to your workspace.')}}
function opportunity(id){const o=get(id),m=matched(o);modal(esc(o.role),esc(o.company)+' · '+esc(o.location),`${o.sample?'<div class="note">This is a fictional example to help you explore Nudge. Add a real opportunity to prepare your own outreach.</div>':''}<div class="eyebrow">WHY THIS COULD BE A FIT</div><h3>${m.length?esc(m.join(' + ')):'A new direction to explore'}</h3><p class="subtext">${m.length?'These skills appear in both your profile and this opportunity.':'Add your skills to your profile to see where your background overlaps.'}</p><div class="eyebrow">THE CONVERSATION STARTER</div><div class="evidence">${esc(o.description)}</div>${o.url?`<a href="${esc(o.url)}" target="_blank" rel="noopener noreferrer">View original source ↗</a>`:''}<p class="explain">Fit is based on matching skill labels, not a hiring prediction. Review the source and recipient before reaching out.</p><div class="actions">${!o.sample?'<button class="secondary danger" id="delete-op">Delete opportunity</button>':''}<button class="primary" id="create-draft">Draft a first hello ↗</button></div>`);$('#create-draft').onclick=()=>{if(!state.profile.name||!state.profile.experience){$('#modal').close();navigate('profile');toast('Add your name and experience, then draft your first hello.');return}const p=state.profile;const draft={id:crypto.randomUUID(),opId:id,company:o.company,role:o.role,sample:o.sample,to:'',subject:`${o.role} — an introduction from ${p.name}`,body:`Hi [recipient name],\n\nI’m ${p.name}${p.headline?', '+p.headline:''}. I’m reaching out about ${o.role.toLowerCase()} opportunities at ${o.company}.\n\n${p.experience}\n\nYour work caught my attention: ${o.description}\n\nWould you be open to a brief conversation about where I could contribute? I’d be happy to share more about my background.\n\nThank you,\n${p.name}`,status:'Draft',created:new Date().toISOString()};state.drafts.unshift(draft);persist();$('#modal').close();editor(draft.id)};if($('#delete-op'))$('#delete-op').onclick=()=>{state.custom=state.custom.filter(x=>x.id!==id);state.saved=state.saved.filter(x=>x!==id);persist();$('#modal').close();page();toast('Opportunity deleted. Existing drafts were kept.')}}
function editor(id){const d=state.drafts.find(d=>d.id===id);modal('Your words. Your next step.',esc(d.company)+' · '+esc(d.role),`<div class="note">${d.sample?'Sample draft for a fictional opportunity.':'Drafted from the experience and opportunity details you provided.'} This version uses a structured template; AI generation is not connected. Replace bracketed text before export.</div><form id="draft-form"><label class="field">To<input id="draft-to" type="email" placeholder="Add a verified email address" value="${esc(d.to)}"></label><label class="field">Subject<input id="draft-subject" required value="${esc(d.subject)}"></label><label class="field">Your message<textarea id="draft-body" class="draft-body" required>${esc(d.body)}</textarea></label><p class="explain">Writing cue: ${esc(state.profile.voice||'Be specific, keep it human, and make a clear, small ask.')}</p><div class="actions"><button type="button" class="secondary" id="copy">Copy text</button><button type="button" class="secondary" id="eml">Download email</button><button type="submit" class="primary">Save draft ✓</button></div></form>`);const sync=()=>{d.to=$('#draft-to').value.trim();d.subject=$('#draft-subject').value;d.body=$('#draft-body').value;persist()};$('#draft-form').onsubmit=e=>{e.preventDefault();sync();$('#modal').close();navigate('drafts');toast('Draft saved. A good first step.')};$('#copy').onclick=async()=>{sync();try{await navigator.clipboard.writeText(`Subject: ${d.subject}\n\n${d.body}`);toast('Copied to clipboard.')}catch{toast('Clipboard unavailable. Select and copy your message.')}};$('#eml').onclick=()=>{sync();if(/[\[\]]/.test(d.body)){toast('Replace the bracketed placeholders before exporting.');return}if(!$('#draft-to').value||!$('#draft-to').checkValidity()){toast('Add a valid recipient email before exporting.');return}download(`${d.company.replace(/[^a-z0-9]/gi,'-')}-draft.eml`,`To: ${d.to.replace(/[\r\n]/g,'')}\r\nSubject: =?UTF-8?B?${btoa(unescape(encodeURIComponent(d.subject.replace(/[\r\n]/g,''))))}?=\r\nMIME-Version: 1.0\r\nContent-Type: text/plain; charset=UTF-8\r\nContent-Transfer-Encoding: base64\r\nX-Unsent: 1\r\n\r\n${btoa(unescape(encodeURIComponent(d.body))).match(/.{1,76}/g).join('\r\n')}`,'message/rfc822');toast('Email draft exported. Nothing has been sent.')}}
function drafts(){const activity=view==='activity';let list=state.drafts.filter(d=>activity?d.status!=='Draft':d.status==='Draft');$('#content').innerHTML=`<div class="eyebrow">${activity?'KEEP THE CONVERSATION GOING':'THOUGHTFUL WORDS OPEN DOORS'}</div><h1 class="page-title">${activity?'Your next steps.':'A first hello, made yours.'}</h1><p class="subtext">${activity?'Track outreach manually as your conversations progress.':'Review, refine, and send when it feels right.'}</p>${list.length?list.map(d=>`<article class="draft-row"><div><h3>${esc(d.subject)}</h3><p>${esc(d.company)} · ${esc(d.role)} ${d.sample?'· Sample':''}</p><p style="margin-top:9px"><span class="pill">${esc(d.status)}</span> &nbsp; ${new Date(d.created).toLocaleDateString()}</p></div><div class="actions"><button class="secondary" data-edit="${d.id}">Edit draft</button><select class="secondary" aria-label="Outreach status for ${esc(d.company)}" data-status="${d.id}">${['Draft','Sent','Replied','Closed'].map(s=>`<option ${s===d.status?'selected':''}>${s}</option>`).join('')}</select><button class="danger" data-delete="${d.id}" aria-label="Delete draft">×</button></div></article>`).join(''):`<div class="empty"><h3>${activity?'Every conversation starts somewhere.':'Your next chapter is unwritten.'}</h3><p>${activity?'Once you send an email yourself, mark its draft as Sent to track it here.':'Explore an opportunity and draft a thoughtful first hello.'}</p><button class="primary" id="explore">Explore opportunities ↗</button></div>`}<p class="explain">Status changes are manual. Nudge does not send emails or read your inbox in this version.</p>`;document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editor(b.dataset.edit));document.querySelectorAll('[data-status]').forEach(s=>s.onchange=()=>{state.drafts.find(d=>d.id===s.dataset.status).status=s.value;persist();page();toast('Outreach status updated.')});document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{const old=state.drafts.find(d=>d.id===b.dataset.delete);modal('Delete this draft?',esc(old.subject),'<p>This removes the saved draft from this browser.</p><div class="actions"><button class="secondary" id="cancel-delete">Keep draft</button><button class="primary" id="confirm-delete">Delete draft</button></div>');$('#cancel-delete').onclick=()=>$('#modal').close();$('#confirm-delete').onclick=()=>{state.drafts=state.drafts.filter(d=>d.id!==old.id);persist();$('#modal').close();page()}});if($('#explore'))$('#explore').onclick=()=>navigate('discover')}
function profile(){const p=state.profile;$('#content').innerHTML=`<div class="eyebrow">THE BEST STARTING POINT IS YOU</div><h1 class="page-title">More than a résumé.</h1><p class="subtext">A few real details. A more personal first impression.</p><div class="panel"><form id="profile-form"><div class="row"><label class="field">Your name<input name="name" value="${esc(p.name)}" required maxlength="100" placeholder="Alex Morgan"></label><label class="field">A short introduction<input name="headline" value="${esc(p.headline)}" maxlength="200" placeholder="a computer science student at UF"></label></div><label class="field">Skills, separated by commas<input name="skills" value="${esc(p.skills)}" placeholder="Python, React, Research"></label><label class="field">Experience you are proud of<textarea name="experience" required maxlength="3000" placeholder="I built a tool that helps students find study groups. I worked on the React interface and interviewed 12 students to understand what mattered to them.">${esc(p.experience)}</textarea><small>Use specific, truthful examples. This becomes the foundation of your drafts.</small></label><label class="field">A note about your voice<textarea name="voice" maxlength="1000" placeholder="Warm and direct. Short paragraphs. I like to ask one clear question.">${esc(p.voice)}</textarea><small>Shown as a writing cue while you edit. Automated voice matching is not connected.</small></label><div class="note">Your profile, opportunities, and drafts stay in this browser’s local storage. They are not synced between devices. Avoid entering sensitive information on shared devices.</div><div class="actions"><button type="button" class="secondary" id="export">Export workspace</button><button class="primary">Save your profile ↗</button></div></form></div>`;$('#profile-form').onsubmit=e=>{e.preventDefault();state.profile=Object.fromEntries(new FormData(e.target));persist();toast('Profile saved. Let’s find your next step.');navigate('discover')};$('#export').onclick=()=>download('nudge-workspace.json',JSON.stringify(state,null,2),'application/json')}
function download(name,body,type){const url=URL.createObjectURL(new Blob([body],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function navigate(v){view=v;location.hash=v;page();window.scrollTo(0,0)}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>navigate(b.dataset.view));window.onhashchange=()=>{view=['discover','saved','drafts','activity','profile'].includes(location.hash.slice(1))?location.hash.slice(1):'discover';page()};$('#settings').onclick=()=>modal('Your workspace, your control.','A private place to prepare your next move.',`<div class="note">This version stores your work in this browser. No email account is connected and no messages are sent automatically.</div><div class="actions"><button class="secondary" id="go-profile">Edit profile</button><button class="secondary" id="backup">Export workspace</button><button class="secondary danger" id="clear">Clear local data</button></div>` )||0;
$('#modal').addEventListener('click',e=>{if(e.target.id==='go-profile'){$('#modal').close();navigate('profile')}if(e.target.id==='backup')download('nudge-workspace.json',JSON.stringify(state,null,2),'application/json');if(e.target.id==='clear'){modal('Clear this browser’s workspace?','Export a backup first if you want to keep your work.','<p>This permanently removes your profile, saved opportunities, and drafts from this browser.</p><div class="actions"><button class="primary" id="clear-confirm">Clear workspace</button></div>')}if(e.target.id==='clear-confirm'){localStorage.removeItem('nudge-v1');location.reload()}});
$('#extension').onclick=()=>modal('A nudge, wherever you browse.','Save an opportunity without losing your place.',`<p class="subtext">The companion Chrome extension captures the current page title and URL. Paste its opportunity notes into Nudge to start a draft.</p><ol class="explain"><li>Download and unzip the extension.</li><li>Open chrome://extensions and enable Developer mode.</li><li>Choose Load unpacked and select the extension folder.</li><li>On an opportunity page, open Nudge and copy its source notes.</li></ol><div class="note">The extension reads the active tab only when you open it. It does not access your inbox or send email. This is an unpacked development extension.</div><div class="actions"><a class="primary" href="nudge-extension.zip" download>Download extension ↓</a></div>`);
window.onhashchange();
